// Applied scenarios reference the single published Parts Sprint catalog; no second parts catalog.
import {PARTS} from '../parts-sprint/catalog.js';
const byId=Object.fromEntries(PARTS.map(p=>[p.id,p]));
const TOOLS='https://kb.vex.com/hc/en-us/articles/13078845924884-Understanding-and-Using-V5-Tools';
const FASTENERS='https://kb.vex.com/hc/en-us/articles/360035952791-Using-V5-Fasteners';
const scenarios=[];
function base(id,mode,difficulty,category,concept,problem,constraints,options,solutions,explanation,source){scenarios.push({id,family:id,mode,difficulty,category,concept,problem,context:'VEX V5 classroom build. Select only from the listed candidates; components already present are stated in the constraints.',constraints,options,solutions,explanation,source,verification:'AI source reviewed; educator review pending'});}
function choose(id,level,concept,problem,constraints,answer,others,explanation){const ids=[answer,...others],category=byId[answer].category;base(id,'choose',level,category,concept,problem,constraints,ids.map(part=>({id:part,label:byId[part].name,componentIds:[part],explanation:part===answer?explanation:`${byId[part].name}: ${byId[part].function} This does not provide the required ${concept.toLowerCase()} under the stated constraints.`})),[[answer]],explanation,byId[answer].source);}
function action(id,mode,level,category,concept,problem,constraints,rows,explanation,source=FASTENERS){base(id,mode,level,category,concept,problem,constraints,rows.map(([label,ids,why],i)=>({id:'a'+i,label,componentIds:ids,explanation:why})),[['a0']],explanation,source);}
function solution(id,level,category,concept,problem,constraints,required,extras,explanation,source){const ids=[...required,...extras];base(id,'solution',level,category,concept,problem,constraints,ids.map(part=>({id:part,label:byId[part].name,componentIds:[part],explanation:required.includes(part)?`${byId[part].function} This supplies one required role in this solution.`:`${byId[part].function} That role is not requested in this minimal additions list; the relevant existing hardware is already supplied.`})),[required],explanation,source||byId[required[0]].source);}
// Choose the Component: distinct functional and assembly constraints.
choose('support-through-frame','Beginner','rotating shaft support','A 1/8-inch shaft must rotate through a flat metal frame. Which addition provides a bearing surface?','The frame and bearing mounting screws are present; no offset from the frame is wanted.','flat-bearing',['nylon-spacer','standoff','shaft-collar'],'A bearing flat supports the rotating shaft. A spacer changes separation and a collar retains axial position; neither replaces the bearing.');
choose('threaded-gap','Beginner','threaded structural separation','Two stationary plates need a rigid gap with screws attaching at the ends of the separator. Which part supplies both separation and threaded attachment?','Select the component type; compatible #8-32 screws and correctly positioned holes are already supplied.','standoff',['nylon-spacer','steel-washer','flat-bearing'],'A standoff separates structures and supplies threaded connection points. An unthreaded spacer cannot receive those screws.');
choose('unthreaded-shaft-gap','Beginner','unthreaded shaft spacing','A gear needs a gap from the frame along its shaft. Which part is intended to create that separation?','Shaft retention and bearings are already present. A threaded structural attachment is not requested.','nylon-spacer',['standoff','t8-key','one-post-retainer'],'A nylon spacer creates an unthreaded gap. The shaft still needs its existing retention; the spacer is not an axial lock.');
choose('positive-axial-retention','Beginner','adjustable shaft retention','A correctly supported 1/8-inch shaft can slide along its axis. Choose an adjustable collar that locks with a Star Drive set screw.','The square shaft and collar are compatible. The task specifies a set-screw lock rather than friction-only retention.','shaft-collar',['flat-bearing','nylon-spacer','gear-insert'],'The shaft collar locks at a selected axial location using its set screw. Bearings support rotation and spacers set gaps but do not perform this lock.');
choose('broad-mount','Beginner','broad flat mounting','A stationary accessory needs a broad, flat mounting surface. Which structural form best matches that requirement?','All candidate structural pieces have adequate strength for this light accessory; no folded corner or deep channel is wanted.','plate',['angle','u-channel','shaft'],'A plate supplies a broad flat mounting area. Selection here concerns the structural form, not a guaranteed hole pattern or load rating.');
choose('joint-reinforcement','Beginner','right-angle joint reinforcement','A frame corner is intended to remain at 90°. Which listed component is specifically intended to reinforce a right-angle joint?','The existing members meet at 90° and verified mounting holes accept the brace.','right-angle-gusset',['nylon-spacer','spur-gear','omni-wheel'],'A 90-degree gusset reinforces the existing right-angle connection; shaft, spacing and wheel components do not brace that joint.');
choose('motion-between-square-hubs','Beginner','square-shaft torque transfer','Two matching 1/8-inch square hub openings must rotate together along one axis. What carries the rotation between them?','Both hub openings are explicitly 1/8-inch square; bearings and axial retention are provided.','shaft',['high-strength-shaft','smart-cable','standoff'],'The 1/8-inch square shaft matches the supplied openings. The 1/4-inch high-strength shaft is a different system and is not interchangeable.');
choose('lateral-rollers','Beginner','sideways passive rolling','A wheel should roll forward but allow sideways movement through small rim rollers. Which wheel type has that behavior?','This is passive sideways freedom, not a claim that one wheel alone creates a holonomic drivetrain.','omni-wheel',['traction-wheel','intake-roller','sprocket'],'An omni wheel uses rim rollers to permit sideways motion while rolling normally in its main direction.');
choose('side-slip-resistance','Beginner','sideways traction','The design needs a wheel that resists sideways sliding at its ground contact. Which listed type matches that goal?','All wheels have suitable diameter and mounting for this comparison; no sideways translation is requested.','traction-wheel',['omni-wheel','mecanum-wheel','spur-gear'],'A traction wheel provides rolling contact that resists sideways slip; roller wheels intentionally permit different lateral behavior.');
choose('object-intake','Beginner','object intake contact','A rotating contact element should pull a game object into an intake. Which listed component is designed for that role?','The mechanism layout, motor and shaft support are already provided. The task concerns the object-contact element.','intake-roller',['sprocket','flat-bearing','standoff'],'The intake roller contacts and draws objects into the mechanism; a sprocket transfers motion through chain rather than being the intended intake contact.');
choose('offset-shaft-support','Intermediate','offset bearing support','A shaft must be supported with its axis offset above the metal mounting surface. Which bearing arrangement matches that geometry?','A compatible offset bearing and shaft combination is available; mounting clearance is verified. A flush bearing location would not meet the required offset.','pillow-block',['flat-bearing','nylon-spacer','nut-bar'],'A pillow block supports a shaft offset from its mounting surface. A spacer alone does not create a mounted bearing support.');
choose('high-strength-bearing-fit','Intermediate','high-strength shaft support','The build uses a 1/4-inch square high-strength shaft. Which listed bearing belongs to that shaft system?','Select a documented system match rather than assuming a scale-free photo proves size.','high-strength-bearing',['flat-bearing','t15-key','gear-insert'],'Use a compatible high-strength shaft bearing for the stated shaft system. A standard-system bearing must not be assumed to fit.');
choose('high-strength-shaft-fit','Intermediate','high-strength torque path','The selected motion components explicitly require the 1/4-inch square high-strength shaft system. Which listed shaft matches?','All hub and bearing specifications have been checked for that system; no adapter is supplied.','high-strength-shaft',['shaft','standoff','chain'],'The high-strength shaft matches the specified 1/4-inch system. A 1/8-inch shaft is not an equivalent dimensional substitute.');
choose('slotted-positioning','Intermediate','slotted mounting adjustment','A stationary bracket needs adjustment along an elongated mounting slot before final tightening. Which structural option provides that feature?','The bracket load and hole access have been checked. The choice concerns a slot, not bending the bracket to fit.','slotted-angle',['angle','steel-washer','shaft-collar'],'The slotted angle offers adjustable positions along its slots. An ordinary angle does not acquire a slot by using a different screw.');
choose('thin-interface','Intermediate','thin interface spacing','Two neighboring parts need a thin ring interface rather than a long gap. Which listed component matches?','A measured thin washer thickness meets the clearance; axial retention is already supplied. No threaded connection is needed here.','steel-washer',['standoff','nylon-spacer','flat-bearing'],'A steel washer provides a thin interface. The choice does not imply every washer has the same thickness or that a washer locks a shaft.');
choose('nylon-thread-lock','Intermediate','nylon-insert thread retention','A #8-32 screw joint needs a nut whose nylon insert resists loosening. Which listed nut provides that mechanism?','The nut size and available space are verified; the question specifies the nylon insert rather than a toothed washer.','nylock-nut',['keps-nut','nut-bar','shaft-collar'],'A Nylock nut resists loosening through its nylon insert. A Keps nut uses a different, toothed-washer mechanism.');
choose('toothed-washer-lock','Intermediate','toothed-washer retention','A stationary screw joint is designed to use a nut with an attached toothed washer bearing against the surface. Which choice matches?','The surface and joint design are appropriate for the toothed washer. No nylon-insert mechanism is specified.','keps-nut',['nylock-nut','nylon-spacer','one-post-retainer'],'A Keps nut uses its toothed washer to resist loosening against a surface. A nut retainer holds a nut for assembly but is not the same locking mechanism.');
choose('nut-capture','Intermediate','captured nut positioning','A compatible hex nut should be held against rotation and located by one post in the structural metal. Which part serves that assembly role?','A separate compatible hex nut and screw are supplied; one locating post is specified.','one-post-retainer',['four-post-retainer','nylock-nut','nylon-spacer'],'The one-post retainer captures the supplied nut and locates it with one post. Four-post geometry is not interchangeable when only one post location is available.');
choose('plastic-thread-receiver','Intermediate','plastic thread-forming connection','A design calls for a plastic bar that receives screws by forming threads, rather than a metal nut at each position. Which candidate matches?','Use the specified V5 nut bar and suitable screws; do not generalize this method to arbitrary plastic.','nut-bar',['standoff','steel-washer','one-post-retainer'],'The V5 nut bar receives screws that form threads in the plastic. A nut retainer instead captures a separately supplied hex nut.');
choose('chain-transmission','Intermediate','motion transfer across spaced shafts','Two compatible sprockets on separated shafts need a flexible linked transmission between them. Which addition performs that role?','The sprockets are aligned and belong to the compatible high-strength chain system. Shaft support is already present.','chain',['spur-gear','smart-cable','standoff'],'Compatible chain transfers motion between the sprockets. A Smart Cable carries electrical signals, not mechanical chain drive.');
choose('sprocket-interface','Intermediate','chain engagement','A compatible high-strength chain must engage a driven rotating component. Which listed candidate provides the chain-engaging teeth?','The selected chain and sprocket system compatibility is documented; this is not direct gear-to-gear contact.','sprocket',['spur-gear','omni-wheel','flat-bearing'],'A sprocket engages compatible chain. A spur gear is intended to mesh directly with another gear, not substitute for a chain sprocket.');
choose('direct-gear-mesh','Intermediate','direct tooth-to-tooth transmission','Two nearby supported shafts need direct tooth-to-tooth transmission. Which listed component can engage a compatible gear directly, without a chain?','The catalogued pinion and mating gear are verified compatible; center distance and shaft support are already checked. Select the direct gear-mesh option rather than a chain-drive component.','spur-gear',['sprocket','chain','shaft-collar'],'The listed metal pinion transfers rotation by meshing directly with the verified mating gear. A sprocket instead engages compatible chain. Arbitrary gears must not be assumed to share tooth geometry.');
choose('compatible-hub-adapter','Advanced','documented square-hub adaptation','A particular gear hub is documented to accept the listed square gear insert, and the insert matches the selected square shaft. Which part supplies the missing hub interface?','Both compatibility statements are explicitly given. Do not assume this insert fits every gear or shaft size.','gear-insert',['flat-bearing','nylon-spacer','standoff'],'The compatible square insert provides the specified gear-to-shaft interface. It does not replace shaft support or axial retention.');
choose('split-collar','Advanced','split-clamp retention','A shaft needs adjustable axial retention. This drawing rules out a direct set-screw point contact and instead requires a collar whose split closes around the shaft. Which candidate meets that constraint?','Shaft/collar size and tool access are verified. The task specifies the clamping mechanism.','clamping-collar',['shaft-collar','rubber-shaft-collar','nylon-spacer'],'A clamping collar closes its split around the shaft. Other retainers may be useful in other designs, but do not meet this specified clamping method.');
choose('nonfree-high-strength-gap','Advanced','high-strength keyed spacing','A spacer is needed on a compatible high-strength shaft and should not freely spin on that shaft. Which listed spacer matches?','The high-strength shaft system is explicitly specified; a generic round-bore spacer is not the requested behavior.','high-strength-spacer',['nylon-spacer','steel-washer','standoff'],'The high-strength spacer belongs to that shaft system and does not freely spin on it; it is not a threaded structural standoff.');
const fx=(id,level,category,concept,problem,constraints,rows,explanation,source)=>action(id,'fix',level,category,concept,problem,'Power is off for mechanical inspection. '+constraints,rows,explanation,source);
fx('axial-slip-check','Beginner','motion','axial slip versus power','A supported shaft slides sideways during a run. The wheel already turns with the shaft. What should be checked first?','No torque-transfer problem has been observed.',[
['Inspect and secure compatible shaft retention',['shaft-collar'],'A collar addresses unwanted axial movement.'],['Install a larger motor',['smart-motor'],'More torque does not stop axial sliding.'],['Replace the Controller',['controller'],'Driver input is not the measured axial fault.'],['Extend the Smart Cable',['smart-cable'],'Cable reach does not locate the shaft axially.']],'Inspect the retention before changing the electrical system. A freely rotating bearing alone does not locate the shaft axially.');
fx('wheel-frame-rub','Beginner','spacing','rotating-part clearance','A wheel rubs the frame. Moving it 3 mm outward by hand stops the rub; shaft support and retention are otherwise correct. What revision is supported?','A compatible 3 mm spacing stack is available and enough shaft engagement remains.',[
['Add the verified spacing and reset retention',['nylon-spacer','shaft-collar'],'The measured offset removes the observed contact.'],['Increase motor power',['smart-motor'],'Power does not create physical clearance.'],['Tighten the wheel against the frame',['shaft-collar'],'This preserves the rubbing contact.'],['Change the radio',['radio'],'Wireless communication cannot remove a mechanical rub.']],'Use the measured clearance to choose spacing, then confirm free movement and retention.');
fx('wrong-tip-slipping','Beginner','tools','tool interface mismatch','A T8 tip is loose in a screw explicitly marked #8-32 Star Drive, not a set screw. What should change?','The screw socket is undamaged and a T15 key is available.',[
['Use the T15 key',['t15-key'],'The specified V5 screw uses the T15 interface.'],['Push harder with T8',['t8-key'],'Extra force does not change the tip size and risks damage.'],['Use a wrench inside the recess',['wrench'],'The wrench holds an external nut, not this internal socket.'],['Replace the bearing',['flat-bearing'],'Bearing support does not address tool fit.']],'Match the tool interface to the stated fastener rather than forcing a poor fit.',TOOLS);
fx('nut-spins-with-screw','Beginner','tools','reaction torque at nut','A compatible nut rotates with the screw instead of the joint tightening. Which next action addresses that observation?','Both sides are accessible and the correct screw driver is already in use.',[
['Hold the nut with the correctly fitting wrench end',['wrench'],'The wrench prevents the nut from turning with the screw.'],['Use a longer Smart Cable',['smart-cable'],'Cable length is unrelated to nut rotation.'],['Remove the washer and assume it is fixed',['steel-washer'],'Removing a washer does not restrain the nut.'],['Replace the motor',['smart-motor'],'Motor output does not hold a stationary assembly nut.']],'A screw and nut need relative rotation; restrain the nut while driving the screw.',TOOLS);
fx('missing-bearing','Beginner','motion','unsupported metal-hole contact','A rotating shaft is rubbing the edge of a raw frame hole, and the specified bearing was omitted. Which correction directly addresses this known omission?','The build calls for a compatible bearing flat at that location and its mounting holes are available.',[
['Install the specified bearing flat',['flat-bearing'],'It supplies the intended rotating support.'],['Put a nut on the unthreaded square shaft',['nylock-nut'],'A threaded nut is not a bearing for this shaft.'],['Increase motor output',['smart-motor'],'More torque does not supply the missing support.'],['Add only a spacer far from the frame',['nylon-spacer'],'A remote spacer does not create the missing bearing surface.']],'Restore the specified support and check alignment before powered testing.');
fx('spacer-as-threaded-support','Beginner','spacing','spacing versus attachment','A builder tries to screw two plates into the ends of an unthreaded nylon spacer. The drawing requires threaded end connections. What should be changed?','A compatible standoff of the required length is available.',[
['Use the specified threaded standoff',['standoff'],'It supplies the missing end threads and separation.'],['Force the screws into the spacer',['nylon-spacer'],'The unthreaded spacer was not specified as a thread-forming receiver.'],['Replace a wheel',['traction-wheel'],'A wheel does not create the structural threaded connection.'],['Use a bearing flat as the separator',['flat-bearing'],'A bearing support is not the required threaded spacer.']],'A spacer and a standoff can both separate things, but only the stated standoff meets the end-attachment requirement.');
fx('support-axis-alignment','Intermediate','motion','misaligned bearing axes','A straight shaft rotates freely through each bearing alone, but binds when both bearing mounts are tightened in the frame. What is the best next diagnostic check?','The shaft is not bent; no other rotating parts are installed.',[
['Check whether the two mounted bearing axes line up',['flat-bearing'],'The isolated supports work, so their combined alignment is the useful next check.'],['Increase motor power',['smart-motor'],'Power can conceal binding rather than remove misalignment.'],['Replace the radio',['radio'],'The fault is reproducible by hand with power off.'],['Add more axial collars without checking alignment',['shaft-collar'],'More retention does not align the bearing axes.']],'The evidence points to checking mounted alignment; it does not prove that every binding shaft has this one cause.');
fx('collar-pressed-bearing','Intermediate','motion','overconstrained axial stack','A shaft turns freely until its collars are pushed tightly against both bearings. Backing one collar away slightly restores free rotation. What should be revised?','Retain the shaft, but allow the observed free-moving axial setup; do not remove all retention.',[
['Reset collar positions to avoid squeezing the rotating stack',['shaft-collar'],'The reported test links binding to the compressed axial arrangement.'],['Force both collars tighter',['shaft-collar'],'That repeats the condition that caused the bind.'],['Install a second Brain',['brain'],'The hand-tested mechanical resistance is not a computing limitation.'],['Remove every bearing',['flat-bearing'],'Loss of support does not create a sound retained assembly.']],'Retain the shaft without compressing the stack into a bind, then retest by hand.');
fx('gear-side-interference','Intermediate','transmission','gear side-face clearance','Two intended mating gears have suitable tooth engagement, but one gear side face scrapes a nearby screw head. What is the best correction to evaluate?','A measured axial offset can clear the head while preserving full intended gear engagement.',[
['Use verified axial spacing and recheck mesh/retention',['nylon-spacer','shaft-collar'],'This targets the side-face interference without assuming the gear teeth are wrong.'],['Drive harder through the scrape',['smart-motor'],'Motor torque does not remove the obstruction.'],['Change only the radio',['radio'],'Radio changes cannot alter mechanical clearance.'],['Move the gear until the teeth barely overlap',['spur-gear'],'Clearing one interference by losing required engagement violates the constraint.']],'Check the offset, engagement and retention together; clearance is not permission to reduce the required gear mesh.');
fx('chain-sprocket-plane','Intermediate','transmission','chain alignment','A compatible chain repeatedly walks toward one sprocket edge. The two sprockets are visibly in different axial planes. What should be checked first?','Chain type is correct; the observation does not establish a motor fault.',[
['Align the sprocket planes and check retention',['sprocket','shaft-collar'],'The visible misalignment is a directly relevant mechanical check.'],['Replace the Controller',['controller'],'Driver input cannot align the sprockets.'],['Install an incompatible chain type',['chain'],'Changing to an incompatible system creates another problem.'],['Remove shaft support',['flat-bearing'],'Unsupported shafts can worsen alignment.']],'Check chain-drive alignment before blaming the electrical system; other causes can be investigated if the problem remains.');
fx('loose-corner-brace','Intermediate','structure','joint movement versus material flex','A 90° corner changes angle because its connection pivots; the individual metal members stay straight. What addition should be evaluated?','The layout accepts a verified 90° gusset and appropriate fasteners.',[
['Brace the corner with the compatible 90° gusset',['right-angle-gusset'],'The moving joint needs reinforcement against changing angle.'],['Only increase wheel diameter',['traction-wheel'],'Wheel diameter does not brace the observed corner joint.'],['Add a shaft spacer at an unrelated axle',['nylon-spacer'],'Axle spacing does not address this structural joint.'],['Change the battery',['battery'],'The fault occurs under hand loading with power off.']],'Distinguish a moving joint from a bending member; the evidence here calls for a corner brace.');
fx('screw-bottoms-in-hole','Intermediate','fasteners','blind-hole depth','A screw stops turning, but the plate remains loose. Its threaded tip reaches the bottom of the blind hole before the head seats. What revision should be evaluated?','Compatible shorter screws are available; adequate thread engagement must still be maintained.',[
['Choose a shorter compatible screw with adequate engagement',['star-screw'],'It can seat the head without bottoming in the supplied hole.'],['Use more force on the same bottomed screw',['t15-key'],'Force does not increase blind-hole depth.'],['Install a longer screw',['star-screw'],'A longer tip worsens the stated bottoming condition.'],['Remove the bearing on another shaft',['flat-bearing'],'Unrelated shaft hardware cannot seat this screw.']],'Length selection must satisfy both seating and engagement; a stopped screw is not proof that the joint is clamped.');
fx('screw-no-thread-reach','Intermediate','fasteners','insufficient screw reach','A screw passes through a material stack but does not reach the nut threads. What should be changed?','Thread type and nut are correct; a longer compatible screw can fit without hitting moving parts.',[
['Select a longer compatible screw with verified safe protrusion',['star-screw'],'The stated failure is insufficient reach.'],['Use a smaller drive tip',['t8-key'],'Tip size does not increase screw length.'],['Add extra spacers to make the stack thicker',['nylon-spacer'],'More stack thickness reduces available reach further.'],['Change the Controller',['controller'],'Controller input does not affect the stationary joint geometry.']],'Measure stack thickness and required engagement, and check the longer screw for clearance.');
fx('nut-retainer-wrong-footprint','Intermediate','fasteners','retainer footprint mismatch','A four-post nut retainer cannot seat because three required post locations are blocked. The drawing allows a compatible one-post retainer at its single available location. What should be evaluated?','The correct hex nut is supplied; the one-post option has been verified against the drawing.',[
['Use the verified one-post retainer',['one-post-retainer'],'Its specified locating footprint fits the available position.'],['Force the four posts against the blocked metal',['four-post-retainer'],'A forced retainer is not seated as designed.'],['Replace the screw driver with a radio',['radio'],'Communication hardware cannot change the locating footprint.'],['Remove the nut and tighten into empty space',['star-screw'],'A screw still needs its specified thread receiver.']],'Locating geometry matters; visually similar retainers are not automatically interchangeable.');
fx('shaft-size-mismatch','Advanced','motion','dimensional system mismatch','A 1/4-inch square high-strength shaft will not fit a component explicitly specified for a 1/8-inch square shaft. What is the best next action?','No approved adapter or machining operation is provided.',[
['Select a documented matching shaft-and-component system',['high-strength-shaft','shaft'],'The dimensions must match throughout the torque path and supports.'],['Hammer the larger shaft into the smaller opening',['high-strength-shaft'],'Forcing does not establish compatibility.'],['Use a longer Smart Cable',['smart-cable'],'A cable does not change the shaft cross-section.'],['Assume the photo scale guarantees a fit',['shaft'],'Scale-free appearance is not dimensional evidence.']],'Verify the whole shaft/hub/bearing system instead of forcing incompatible cross-sections.');
fx('thread-wont-start','Advanced','fasteners','thread compatibility diagnostic','A screw will not start by hand in a nut. Thread specifications have not yet been checked. What is the best next diagnostic step?','There is no evidence yet proving whether the cause is wrong thread, damage or misalignment.',[
['Check matching thread specifications, alignment and thread condition',['star-screw','nylock-nut'],'This tests the plausible causes before applying force.'],['Force it with a larger handle',['t15-driver'],'Force can damage threads and does not prove compatibility.'],['Declare the motor too weak',['smart-motor'],'This is a stationary hand-assembly problem.'],['Assume every nut in the bin is interchangeable',['keps-nut'],'Nut appearance alone does not prove thread compatibility.']],'Use the specifications and inspect the joint; do not present one unverified cause as certain.');
fx('supported-gear-tilt','Advanced','transmission','shaft support under gear load','A gear turns correctly without load, but its long unsupported shaft end visibly tilts under load and the gears lose alignment. What should be evaluated next?','The gear tooth systems are compatible; the layout offers a verified second bearing mounting location near the loaded end.',[
['Add the compatible bearing support and recheck alignment',['flat-bearing'],'The observed deflection makes additional support a relevant design revision.'],['Remove the existing bearing',['flat-bearing'],'Removing support worsens the observed unsupported condition.'],['Only fit a longer electrical cable',['smart-cable'],'Cable length does not resist shaft deflection.'],['Run at greater motor output without checking support',['smart-motor'],'More loading does not correct the support geometry.']],'Support and alignment are distinct from power; verify the revised mechanism physically.');
fx('drive-wheel-slip-interface','Advanced','motion','torque coupling versus axial retention','The shaft rotates but a compatible wheel hub turns independently on it. Axial position is stable. The documented wheel coupling is missing. What correction addresses the lost torque transfer rather than adding more axial retention?','The exact wheel, shaft and lock-bar interface has been verified; the problem is rotation relative to the shaft, not sideways movement.',[
['Install the specified drive shaft lock bar',['lock-bar'],'The documented interface couples the driven part to the square shaft.'],['Only add a spacer beside the wheel',['nylon-spacer'],'Spacing does not provide the omitted torque coupling.'],['Only move an axial collar farther outward',['shaft-collar'],'Axial retention is already stable and is not the stated missing interface.'],['Change the robot radio',['radio'],'Communication does not couple the hub mechanically.']],'Do not confuse transmitting rotation with retaining axial position.');
// Tools: supplied interfaces and dimensions determine an action, never image-based size guessing.
action('t15-structural-screw','tools','Beginner','tools','specified screw interface','A structural joint uses a V5 #8-32 Star Drive screw. Which listed tool should drive its socket?','The fastener is a normal Star Drive screw, not a Star Drive set screw.',[
['T15 Star Drive key',['t15-key'],'The stated V5 #8-32 Star Drive screw uses T15.'],['T8 Star Drive key',['t8-key'],'T8 is for the stated V5 Star Drive set-screw applications, not this screw.'],['Open end wrench inside the socket',['wrench'],'The wrench holds an external nut/standoff rather than driving this recess.'],['Crimping tool',['crimp-tool'],'Crimping connectors does not drive a screw socket.']],'Select the tip for the specified screw interface.',TOOLS);
action('t8-collar-setscrew','tools','Beginner','tools','specified set-screw interface','An adjustable Star Drive shaft collar needs its small Star Drive set screw secured. Which tool matches?','The fastener is explicitly the V5 Star Drive set screw in the collar.',[
['T8 Star Drive key',['t8-key'],'VEX specifies T8 for these Star Drive set screws.'],['T15 Star Drive key',['t15-key'],'T15 drives the normal #8-32 Star Drive screws, not this smaller set-screw interface.'],['Crimping tool',['crimp-tool'],'A cable connector tool is not a set-screw driver.'],['Open end wrench in the recess',['wrench'],'The external wrench does not fit the internal star interface.']],'Distinguish screw thread identity from the stated drive interface; the tip must match the recess.',TOOLS);
action('wrench-small-standoff','tools','Beginner','tools','standoff reaction tool','A #8-32 standoff rotates when its screw is driven. Which wrench use is documented for holding it?','Use the standard V5 open end wrench; select the end based on the named hardware, not photo size.',[
['Hold it with the smaller wrench end',['wrench','standoff'],'VEX lists #8-32 standoffs for the smaller end.'],['Put the T8 tip against the outside flats',['t8-key'],'The small star tip does not grip the external hex body.'],['Crimp the standoff',['crimp-tool'],'Crimping is not the documented way to hold the standoff.'],['Grip the rotating screw socket with the larger wrench end',['wrench'],'The wrench end is for external flats, not the screw recess.']],'Restrain the threaded support with the fitting wrench while driving the screw.',TOOLS);
action('wrench-large-nylock','tools','Beginner','tools','Nylock reaction tool','A supplied #8-32 Nylock nut needs to be held while a compatible screw is driven. Which standard V5 wrench end is specified?','The nut is explicitly Nylock, not the low-profile nut.',[
['Larger end of the V5 wrench',['wrench','nylock-nut'],'VEX lists #8-32 Nylock nuts for the larger end.'],['Smaller end because every #8-32 part has the same outside size',['wrench'],'Thread identity does not imply the same external hex size.'],['T8 key inside the nut thread',['t8-key'],'The thread is not a T8 drive socket.'],['Crimping tool on the nylon insert',['crimp-tool'],'Damaging the insert is not a fastening method.']],'Match the nut’s external size to the documented wrench end.',TOOLS);
action('wrench-two-side-task','tools','Intermediate','tools','two-sided fastening','A V5 #8-32 Star Drive screw and a Nylock nut turn together. Which tool combination lets the builder tighten them relative to each other?','Both sides are accessible; the nut and screw threads match.',[
['T15 driver at the screw and fitting wrench at the nut',['t15-driver','wrench'],'One drives the screw while the other supplies reaction at the nut.'],['T8 key at the screw and spacer at the nut',['t8-key','nylon-spacer'],'The tip is wrong and a spacer does not restrain the nut.'],['Two crimping tools',['crimp-tool'],'Connector tools do not provide the required socket/hex engagement.'],['Only a shaft collar beside the nut',['shaft-collar'],'Axial shaft retention does not hold this threaded joint.']],'Use the two appropriate interfaces together; a correctly sized screw tool alone cannot stop a freely turning nut.',TOOLS);
action('hex-socket-separation','tools','Intermediate','tools','hex versus star socket','The available screw is explicitly marked internal hex, and the kit tray shown in the choices contains only star keys and a wrench. What should happen before tightening?','The required hex-key size is not supplied. Do not infer it from a scale-free photograph.',[
['Obtain the specified correctly sized hex key',['hex-screw'],'The hex recess requires its matching hex key; measure or read the specification first.'],['Force the T15 star key into the hex recess',['t15-key'],'A different recess shape is not proven compatible.'],['Use T8 because it is smaller',['t8-key'],'Being smaller does not make the interface correct.'],['Use the external wrench inside the recess',['wrench'],'The wrench is not an internal hex key.']],'Identify both the recess shape and required size instead of forcing a near fit.',FASTENERS);
action('blind-hole-length-choice','tools','Intermediate','fasteners','screw seating and depth','A screw passes through a 4 mm plate stack into a blind threaded hole. Usable threaded depth is 8 mm; required engagement is at least 5 mm. Which candidate length satisfies both?','Lengths are measured below the head. Thread types match; ignore head height. The tip must not exceed the stated usable depth.',[
['10 mm screw',['star-screw'],'10−4=6 mm engagement: at least 5 mm and no more than 8 mm.'],['8 mm screw',['star-screw'],'8−4=4 mm engagement, below the 5 mm requirement.'],['14 mm screw',['star-screw'],'14−4=10 mm, exceeding the 8 mm blind-hole depth.'],['6 mm screw',['star-screw'],'6−4=2 mm is insufficient engagement.']],'Subtract stack thickness from below-head length, then test both minimum engagement and maximum depth. The supplied dimensions are an instructional design specification, not a standard VEX screw-length claim.');
action('through-joint-protrusion','tools','Intermediate','fasteners','engagement and moving-part clearance','A screw must pass a 6 mm stack and engage a nut for at least 4 mm. A moving part limits total below-head length to 12 mm. Which listed length meets both constraints?','The threads match. Candidate dimensions are instructional; lengths are below the head.',[
['11 mm screw',['star-screw'],'It leaves 5 mm beyond the stack and stays below the 12 mm clearance limit.'],['8 mm screw',['star-screw'],'Only 2 mm remains for the required 4 mm nut engagement.'],['15 mm screw',['star-screw'],'It exceeds the moving-part clearance limit.'],['6 mm screw',['star-screw'],'It ends at the stack and cannot meet the required nut engagement.']],'Check minimum engagement and maximum protrusion together; a longer screw is not automatically better.');
action('standoff-wrench-length','tools','Intermediate','tools','wrench interface versus standoff length','Two #8-32 V5 standoffs have different lengths but the same documented external hex type. Which tool decision follows the VEX tool guidance?','Both are standard #8-32 V5 standoffs, not different hardware systems.',[
['Use the smaller wrench end for either standoff',['wrench','standoff'],'The tool guidance states that standoff length does not change the specified wrench end.'],['Choose the large wrench end only for the longer standoff',['wrench'],'Length is not the external hex interface size.'],['Use T15 on the standoff outside flats',['t15-key'],'The T15 tip drives the screw socket, not the standoff flats.'],['Use a spacer instead of holding the standoff',['nylon-spacer'],'Spacing does not supply reaction torque.']],'Tool fit follows the outside interface, not the standoff’s length.',TOOLS);
action('driver-access-constraint','tools','Advanced','tools','tool access versus matching tip','A normal V5 #8-32 Star Drive screw needs tightening. The T15 screwdriver handle cannot fit the available space, but the T15 L-key can fully engage the socket. What choice meets both constraints?','The L-key has adequate turning room; the T8 key is not the required socket size.',[
['Use the fully engaging T15 L-key',['t15-key'],'It matches the specified drive and the stated access geometry.'],['Use T8 because its body is smaller',['t8-key'],'A smaller tool body does not excuse a wrong tip size.'],['Use the T15 screwdriver without seating its tip fully',['t15-driver'],'Partial engagement violates the supplied full-engagement requirement.'],['Hold only the nut and leave the screw loose',['wrench'],'Holding the nut does not complete the required tightening.']],'Evaluate interface and physical access together instead of choosing by tool appearance alone.',TOOLS);
action('universal-joint-set-screw','tools','Advanced','tools','joint set-screw interface','The small V5 Star Drive set screw in a Universal Joint must be adjusted. Which tool/interface pairing is documented?','The hardware is explicitly the Star Drive set-screw version. No hex-socket substitution is implied.',[
['T8 tip at the small Star Drive set screw',['t8-key'],'VEX lists Universal Joint Star Drive set screws among the T8 applications.'],['T15 because all #8-32 threads use one tip',['t15-key'],'Thread identity and socket size are different specifications.'],['Wrench jaws inside the small star recess',['wrench'],'An external wrench does not drive this recess.'],['Crimping tool at the joint',['crimp-tool'],'Connector crimping is unrelated to adjusting the set screw.']],'Read the specified drive interface; do not generalize from another fastener with the same thread designation.',TOOLS);
action('washer-spacer-stack','tools','Advanced','spacing','measured gap stack','A rotating part needs a 3 mm axial gap from a stationary surface. Available pieces are a measured 1 mm washer and measured 2 mm spacers. Which minimal stack gives exactly 3 mm?','All bore sizes are compatible; retention and bearing support already exist. These measured thicknesses are supplied example values.',[
['One 1 mm washer plus one 2 mm spacer',['steel-washer','nylon-spacer'],'1+2=3 mm meets the specified gap with two pieces.'],['Only one 1 mm washer',['steel-washer'],'1 mm leaves the gap 2 mm short.'],['Two 2 mm spacers',['nylon-spacer'],'4 mm exceeds the exact 3 mm requirement.'],['One threaded standoff of unknown length',['standoff'],'An unknown length cannot establish the measured gap, and a threaded structural connector is not specified.']],'Use measured dimensions and compatible bores; part names alone do not prove a clearance stack.');
// Build a Solution: choose the complete minimum additions list; existing parts and alternatives are constrained.
solution('support-and-retain','Beginner','motion','support plus axial retention','Complete a rotating shaft installation with both support through a flat frame and adjustable axial retention.','The compatible shaft, wheel, mounting screws and frame are supplied. Use a set-screw collar for the specified adjustable retention. Select the minimum missing component types.',['flat-bearing','shaft-collar'],['nylon-spacer','standoff','radio'],'A bearing supplies rotational support and a collar supplies axial retention. Neither role substitutes for the other.');
solution('gap-and-attachment','Beginner','spacing','threaded gap plus screw drive','Prepare a threaded separation between two stationary plates and the tool to drive the supplied Star Drive screws.','The measured-length #8-32 standoff fits the drawing. Nuts are not required; a second builder already holds the standoff with a wrench.',['standoff','t15-key'],['nylon-spacer','t8-key','flat-bearing'],'The standoff receives the supplied screws at the specified gap; T15 drives those normal V5 Star Drive screws.');
solution('wheel-gap-retain','Beginner','spacing','wheel spacing plus axial retention','Add a measured unthreaded gap beside a wheel and prevent the supported shaft from sliding sideways.','The compatible shaft, wheel and bearings are present. The verified spacer length is available; adjustable Star Drive set-screw retention is required.',['nylon-spacer','shaft-collar'],['standoff','t15-key','nut-bar'],'The spacer sets the gap and the collar retains axial position. A spacer alone does not lock the shaft.');
solution('screw-nut-tools','Beginner','tools','drive plus reaction','Choose tools to tighten an existing normal V5 #8-32 Star Drive screw into an accessible compatible nut.','The screw and nut are supplied. Both sides are accessible. Choose one driver and one reaction tool; the handled T15 screwdriver is not among candidates.',['t15-key','wrench'],['t8-key','nylon-spacer','crimp-tool'],'T15 engages the screw socket and the wrench holds the nut against rotation.',TOOLS);
solution('chain-bridge','Beginner','transmission','sprockets plus chain','Link two supported shafts by a chain transmission.','Existing shafts accept the catalogued sprockets. The two compatible high-strength sprockets and matching chain are the only missing component types; alignment and retention are supplied.',['sprocket','chain'],['spur-gear','smart-cable','nylon-spacer'],'A chain drive requires compatible sprockets and chain; it does not use a Smart Cable as a mechanical link.');
solution('brace-and-drive-tool','Beginner','structure','corner brace installation','Reinforce an existing 90° frame corner and choose a tool to drive the supplied normal Star Drive mounting screws.','A verified 90° gusset mounting pattern fits. Nuts are captive in the existing frame, so no reaction wrench is needed in this minimal list.',['right-angle-gusset','t15-key'],['nylon-spacer','t8-key','wrench'],'The gusset reinforces the corner and T15 drives the supplied screws. The existing captive nuts make a wrench an unnecessary addition here.');
solution('high-strength-motion-path','Intermediate','motion','matching high-strength support system','Complete a torque path requiring the 1/4-inch square high-strength shaft system.','The wheel/hub and retention hardware are supplied and verified for that system. Both the shaft and its compatible bearing type are missing; no adapter is supplied.',['high-strength-shaft','high-strength-bearing'],['shaft','flat-bearing','standoff'],'Choose the matching shaft and bearing system together; the standard 1/8-inch components are not dimensional substitutes.');
solution('offset-and-lock','Intermediate','motion','offset support with adjustable retention','Support a compatible shaft above its structural mounting surface and retain its axial position.','The shaft, hub, mounting fasteners and tools are supplied. The design needs an offset bearing location and a set-screw collar.',['pillow-block','shaft-collar'],['flat-bearing','nylon-spacer','standoff'],'The pillow block supplies the required offset support; the collar supplies retention. A flush support does not satisfy the required axis location.');
solution('thin-interface-and-gap','Intermediate','spacing','two measured spacing roles','Provide a thin metal interface at one position and a longer unthreaded gap at another position on a compatible shaft.','The drawing and measured parts explicitly require both a thin steel washer and a longer nylon spacer. Bearings and collars are already fitted; no threaded support is needed.',['steel-washer','nylon-spacer'],['standoff','flat-bearing','nylock-nut'],'The two distinct measured locations require different spacing roles; one unknown generic separator cannot be assumed to satisfy both.');
solution('nylock-joint-install','Intermediate','fasteners','nylon locking joint installation','Prepare a stationary joint that specifically requires nylon-insert resistance to loosening.','A normal compatible #8-32 Star Drive screw is supplied. The missing nut and two tools must be selected; both sides are accessible.',['nylock-nut','t15-key','wrench'],['keps-nut','t8-key','nylon-spacer'],'The Nylock nut meets the specified locking mechanism; T15 drives the screw and a fitting wrench holds the nut.',TOOLS);
solution('keps-joint-install','Intermediate','fasteners','toothed washer joint installation','Prepare a joint whose drawing requires an attached toothed washer acting against the surface.','A compatible normal V5 Star Drive screw and T15 driver are already supplied. Select the missing nut and tool to hold it. The joint surface was verified for the drawing.',['keps-nut','wrench'],['nylock-nut','t8-key','standoff'],'A Keps nut supplies the required toothed-washer action and the wrench supplies reaction; nylon insert locking is a different specified mechanism.',TOOLS);
solution('one-post-capture-install','Intermediate','fasteners','captured nut plus screw driving','Complete a mount where a supplied hex nut must be captured at exactly one available locating-post position.','The verified one-post retainer fits. A supplied normal V5 Star Drive screw needs its driving tool. The retainer holds the nut; do not add an unnecessary reaction wrench.',['one-post-retainer','t15-key'],['four-post-retainer','wrench','t8-key'],'The one-post retainer fits the stated footprint and captures the nut; T15 drives the normal Star Drive screw.');
solution('retention-with-adjustment-tool','Intermediate','motion','axial retention and set-screw tool','Add adjustable axial retention and the matching tool to a supported compatible shaft.','The design specifies a Star Drive set-screw collar. The normal structural screw tool is not the set-screw tool. Bearings and spacing are already supplied.',['shaft-collar','t8-key'],['t15-key','flat-bearing','nylon-spacer'],'The collar performs the retention and T8 drives its specified Star Drive set screw.',TOOLS);
solution('slotted-bracket-install','Intermediate','structure','adjustable mounting plus drive tool','Mount an accessory so its position can be adjusted along a slot before the joint is tightened.','The verified slotted angle fits the accessory and frame. Normal Star Drive screws and captive nuts are supplied. Only the structural form and its screw-driving tool are missing.',['slotted-angle','t15-key'],['angle','t8-key','nylon-spacer'],'The slotted angle provides the required adjustment range; T15 drives the supplied normal Star Drive screws.');
solution('gear-support-interface','Advanced','transmission','gear interface plus shaft support','Complete a gear installation that needs both the documented gear-hub adapter and a bearing support at a flat frame location.','The gear hub explicitly accepts the listed square insert. Insert, shaft and bearing size compatibility is verified. Shaft, gear, fasteners and axial retention already exist.',['gear-insert','flat-bearing'],['nylon-spacer','shaft-collar','standoff'],'The insert supplies the gear-to-shaft interface; the bearing supports rotation through the frame. Neither one replaces the other.');
solution('sprocket-offset-stack','Advanced','transmission','chain alignment plus retained position','Move an existing compatible sprocket into its mating sprocket plane, then retain the adjusted axial position.','A measured nylon spacer creates exactly the required shift; adequate hub engagement remains. Shafts, bearings, chain and both sprockets are supplied. The specified retention uses a Star Drive collar and its set-screw tool.',['nylon-spacer','shaft-collar','t8-key'],['t15-key','standoff','spur-gear'],'The spacer creates the verified alignment shift, the collar retains it, and T8 secures that collar’s specified set screw. More motor power would not align the chain.');
solution('high-strength-nonfree-spacing','Advanced','motion','high-strength support and keyed separation','Support a supplied high-strength shaft and space a component without the spacer freely spinning on the shaft.','The design specifically uses compatible high-strength bearings and spacers. Shaft, hub, retention, frame and fasteners are already supplied.',['high-strength-bearing','high-strength-spacer'],['flat-bearing','nylon-spacer','standoff'],'The two high-strength-system components meet the stated support and non-free-spinning spacing requirements; no cross-system substitution is assumed.');
solution('split-clamp-with-offset-support','Advanced','motion','offset support plus split-clamp constraint','Support the shaft at an offset mounting location and retain it using a collar that closes a split around the shaft.','The compatible pillow block and split-clamp collar have verified mounting/tool access. Shaft, driven hub and all necessary tightening tools are already supplied. No direct set-screw collar is allowed by this drawing.',['pillow-block','clamping-collar'],['flat-bearing','shaft-collar','nylon-spacer'],'The offset bearing meets the axis-location constraint; the clamping collar meets the specified retention mechanism.');
solution('structural-threaded-brace','Advanced','structure','corner stability plus threaded separation','A two-level frame needs a reinforced 90° corner and a rigid measured threaded separation between levels.','The verified 90° gusset and standoff fit separate specified positions. Screws, captive nuts and tools already exist. No rotating shaft runs through this assembly.',['right-angle-gusset','standoff'],['nylon-spacer','flat-bearing','shaft-collar'],'The brace resists angle change at the corner while the standoff provides the specified threaded separation; these solve different structural constraints.');
solution('supported-torque-coupling','Advanced','motion','torque coupling with shaft support','Complete a driven wheel interface whose square-shaft coupling and flat-frame bearing support are missing.','The exact wheel/shaft/drive-lock-bar and bearing compatibility has been verified. Wheel, shaft, fasteners and axial collars are supplied. The goal is torque transfer plus support, not additional axial retention.',['lock-bar','flat-bearing'],['nylon-spacer','shaft-collar','radio'],'The drive shaft lock bar supplies the documented wheel-to-shaft coupling, and the bearing supplies support. An extra axial collar does not replace the missing coupling.');
// Repeated underlying mechanisms across modes share a family ID. Mode-specific presentation is not a new family.
const sharedFamilies={
 'missing-bearing':'support-through-frame',
 'axial-slip-check':'positive-axial-retention',
 'spacer-as-threaded-support':'threaded-gap',
 'wrong-tip-slipping':'t15-structural-screw',
 'nut-spins-with-screw':'wrench-two-side-task',
 'screw-bottoms-in-hole':'blind-hole-length-choice',
 'screw-no-thread-reach':'through-joint-protrusion',
 'shaft-size-mismatch':'high-strength-shaft-fit',
 'nut-retainer-wrong-footprint':'nut-capture',
};
for(const s of scenarios){if(sharedFamilies[s.id])s.family=sharedFamilies[s.id];}
export const SCENARIOS=Object.freeze(scenarios);
